/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: Message, ReviewSections, TitleNumbers, ReviewLookupFit, ReviewStatus
 *   Functions: normalizedTitle, titleTier, editionKey, releaseGroups, reviewSections, titleNumbers,
 *              reviewLookupFit, reviewAppliedAgain, candidateReason, elapsedText, progressPhaseKey,
 *              reviewLookupStatus
 * Internal
 *   Types: Candidate, Cause
 *   Functions: fold, spaced, nameParts, positionText, reason
 *   Constants: brackets, POSITION
 * @end-catalog */

/**
 * The existing-Album review's own reading of its lookup view, beside the next step it shares with the import page
 * (lookupNextStep.ts, which stays as it is): why nothing matched, which releases could match by title, one reason per candidate,
 * the active run's progress, when a retrying run retries and which retry of how many (too many requests apart from an unavailable
 * source), why MusicBrainz's retries ran out or a run stopped, whether the status points at the name box, and the Disc and Track
 * Numbers the Album's track titles carry. The review's lookup brief
 * (reviewLookupBrief.ts) reads its fit and applied-again checks too. Owner rules: docs/business-rules.md
 * (Administrator Metadata Lookup, next-step bullet); the comparison is described in docs/features/admin-workbench.md. Pure; the
 * review summary imports it, and so does the chooser shared with the import page, which loads it with the chooser chunk but never
 * calls it there (lookupNextStep.ts and the import page's initial chunks stay unchanged).
 */
import type { ReviewLookupView } from './importLookupApi';

type Candidate = ReviewLookupView['candidates'][number];
/** A message of the review summary or a card: a key in the admin text hook's form and its variables. */
export type Message = { key: string; values?: Record<string, string | number> };

const fold = (value: string) => value.normalize('NFKC').toLowerCase().trim();
const brackets = /[「」『』()[\]]/gu;
/** Brackets turned into spaces and whitespace collapsed. */
const spaced = (value: string) => value.replace(brackets, ' ').replace(/\s+/gu, ' ').trim();
/** A saved Artist name folded, then for "Name -Part-" or "Name (Part)" each of its parts as well. */
const nameParts = (name: string) => { const folded = fold(name), parts = /^(.*?)\s*[-(]\s*(.+?)\s*[-)]$/u.exec(folded); return [spaced(folded), ...(parts ? parts.slice(1) : [])].filter(Boolean); };
/**
 * A title compared for a possible match: a trailing credit removed (after a full-width "／", or after an ASCII "/" with spaces on
 * both sides, so "Love/Hate" or "Fate/Zero …" keep theirs), then NFKC-folded (width) and lower-cased, brackets 「」『』()[] turned
 * into spaces (NFKC already folded the full-width ones), whitespace collapsed, and a leading or trailing saved primary Artist name
 * (or one part of a decorated name) removed. A title that is only a credit or only the Artist name keeps it.
 */
export function normalizedTitle(title: string, artists: readonly string[]): string {
  let value = spaced(fold(title.replace(/\s*／[^／]+$|\s+\/\s+[^/]+$/u, '') || title));
  for (const part of artists.flatMap(nameParts)) {
    if (value.startsWith(`${part} `)) value = value.slice(part.length + 1).trim();
    if (value.endsWith(` ${part}`)) value = value.slice(0, -part.length - 1).trim();
  }
  return value;
}
/** How a candidate's normalized title compares with the searched one: equal, one containing the other, or neither (or empty). */
export const titleTier = (candidate: string, searched: string): 'same' | 'similar' | 'other' => !candidate || !searched ? 'other'
  : candidate === searched ? 'same' : candidate.includes(searched) || searched.includes(candidate) ? 'similar' : 'other';

/** Candidates sharing title, Artist, label, date, barcode, catalogue number and track count are editions of one release. */
export const editionKey = (candidate: Candidate) => JSON.stringify([candidate.title, candidate.artist, candidate.label, candidate.date, candidate.barcode, candidate.catalogNumber,
  candidate.trackCount]);
/** Releases (lists of editions) in first-appearance order, each edition list in the given order. */
export function releaseGroups(candidates: readonly Candidate[]): Candidate[][] {
  const groups = new Map<string, Candidate[]>();
  for (const candidate of candidates) { const key = editionKey(candidate); groups.set(key, [...groups.get(key) ?? [], candidate]); }
  return [...groups.values()];
}

export type ReviewSections = { possible: Candidate[][]; others: Candidate[][]; rest: Candidate[][] };
/**
 * The review chooser's sections while nothing matched as a group. Possible matches are candidates whose tracks fit (unverified)
 * with the same normalized title as the searched text or, when none has it, a similar one; the other candidates that fit follow
 * with a similar title first, then a credit that agrees with the Album's primary Artists, then the server's order; candidates
 * that do not fit or could not be read come last. Every list counts releases.
 */
export function reviewSections(candidates: readonly Candidate[], searched: string, artists: readonly string[]): ReviewSections {
  const key = normalizedTitle(searched, artists), tier = (candidate: Candidate) => titleTier(normalizedTitle(candidate.title ?? '', artists), key);
  const fit = candidates.filter(candidate => candidate.status === 'unverified' || candidate.status === 'matching');
  const same = fit.filter(candidate => tier(candidate) === 'same'), possible = same.length ? same : fit.filter(candidate => tier(candidate) === 'similar');
  const rank = (candidate: Candidate) => (tier(candidate) === 'similar' ? 0 : 2) + (candidate.artistMismatch === false ? 0 : 1);
  return { possible: releaseGroups(possible), others: releaseGroups(fit.filter(candidate => !possible.includes(candidate)).sort((a, b) => rank(a) - rank(b))),
    rest: releaseGroups(candidates.filter(candidate => !fit.includes(candidate))) };
}

/**
 * A position at the start of a track title: a Disc and Track Number ("1-01", "1.01") or a Track Number ("01"), then a period and
 * any spaces, a spaced period, hyphen or dash, or spaces, and more of the title. It reads exactly the positions the server's
 * Track-title search removes (src/administration/lookup/lookupTitlePositions.ts), so "01_X", "12) X" or "01-X" has none.
 */
const POSITION = /^(?:(\d{1,2})[-.](\d{1,3})|(\d{1,3}))(?:\.\s*|\s+\.\s+|\s+[-–—]\s+|\s+)(?=\S)/u;
/** A title as positions read it: whitespace collapsed and trimmed; empty over 1024 characters, where the server reads none. */
const positionText = (title: string) => title.length > 1024 ? '' : title.replace(/\s+/gu, ' ').trim();
export type TitleNumbers = {
  /** The empty numbers to fill, by slot; a Disc Number only from a Disc-and-Track position and only where it was captured. */
  numbers: Record<string, { discNumber?: number; trackNumber?: number }>;
  /** How many members get a number (0: every number the titles give is already there). */
  count: number;
  /** Whether the titles give each member a Disc and Track Number ("1-01 "), not a Track Number alone ("01."). */
  disc: boolean;
};
/**
 * The Disc and Track Numbers the saved track titles give, or null unless the server's Track-title guard accepts them: every
 * member's title starts with a position of one form, every number is at least 1, and the positions increase strictly by Disc
 * Number (a missing one counting as 1), then Track Number, in Album order; a lone member counts only with a Disc Number and a
 * Track Number written with a leading zero ("1-01 "), so titles such as "7 Rings", "1-2 Punch" or a single "01 Intro" never count.
 * Only empty numbers fill, a Disc Number only where the review captured one; a saved number that disagrees with its own title, or
 * titles on several discs where a member's Disc Number cannot be filled, give none, so filling never makes two members claim one
 * position.
 */
export function titleNumbers(tracks: readonly { slotId: string; title: string; discNumber?: number | null; trackNumber: number | null }[],
  captured: ReadonlySet<string>): TitleNumbers | null {
  const texts = tracks.map(track => positionText(track.title)), found = texts.map(text => POSITION.exec(text)), disc = found[0]?.[3] === undefined;
  if (!found.length || found.some(match => !match || (match[3] === undefined) !== disc)
    || (found.length < 2 && (!disc || !/^\d{1,2}[-.]0\d/u.test(texts[0])))) return null;
  const matches = found as RegExpExecArray[];
  const positions = matches.map(match => disc ? [Number(match[1]), Number(match[2])] : [1, Number(match[3])]);
  if (positions.some(([discNumber, trackNumber], index) => discNumber < 1 || trackNumber < 1
    || (index > 0 && (discNumber < positions[index - 1][0] || (discNumber === positions[index - 1][0] && trackNumber <= positions[index - 1][1]))))) return null;
  if (tracks.some((track, index) => (track.trackNumber !== null && track.trackNumber !== positions[index][1]) || (disc && track.discNumber != null && track.discNumber !== positions[index][0]))
    || (disc && new Set(positions.map(([discNumber]) => discNumber)).size > 1 && tracks.some(track => track.discNumber == null && !captured.has(track.slotId)))) return null;
  const numbers: TitleNumbers['numbers'] = {};
  tracks.forEach((track, index) => {
    const fill = { ...(track.trackNumber === null ? { trackNumber: positions[index][1] } : {}),
      ...(disc && track.discNumber == null && captured.has(track.slotId) ? { discNumber: positions[index][0] } : {}) };
    if (Object.keys(fill).length) numbers[track.slotId] = fill;
  });
  return { numbers, count: Object.keys(numbers).length, disc };
}

const reason = (key: string, values?: Message['values']): Message => ({ key: `catalog_review.lookup_${key}`, values });
type Cause = 'durations' | 'paired_durations' | 'pairing' | 'release_durations';
/**
 * What a no-match run's candidates say: for an Album without members, its releases with the searched name; else the releases its
 * tracks fit (the possible matches, else those whose titles differ), whether they are possible matches, and why none was applied,
 * with the count of members without a duration; null for a real no match.
 */
export type ReviewLookupFit = { members: false; releases: Candidate[][] }
  | { members: true; possible: boolean; releases: Candidate[][]; cause: Cause; unknown: number };
export function reviewLookupFit(lookup: ReviewLookupView, context: { members: number; searched: string; artists: readonly string[] }): ReviewLookupFit | null {
  const { possible, others } = reviewSections(lookup.candidates, context.searched, context.artists);
  if (!context.members) return { members: false, releases: possible };
  const fit = possible.length ? possible : others, pairings = fit.flat().map(candidate => candidate.comparison?.subset?.pairing), unknown = lookup.disclosure?.unknownLocalDurations ?? 0;
  const cause: Cause | null = unknown ? pairings.includes('unique') ? 'paired_durations' : 'durations' : pairings.includes('unique') ? 'release_durations' : pairings.includes('ambiguous') ? 'pairing' : null;
  return fit.length && cause ? { members: true, possible: possible.length > 0, releases: fit, cause, unknown } : null;
}
/** The release this run applied for its Album values only whose pairing a saved number has since made single, or undefined. */
export const reviewAppliedAgain = (lookup: ReviewLookupView, status: string) => {
  const applied = lookup.applied;
  return status === 'lookup.applied' && applied?.run === lookup.run && applied.choice === 'chosen' && applied.pairs === null
    ? lookup.candidates.find(candidate => candidate.key === applied.candidateKey && candidate.comparison?.subset?.pairing === 'unique' && candidate.comparison.trackCount.local) : undefined;
};
/**
 * One reason per review card without a proposal, the first that applies: details not fetched, too few audio tracks, a tracklist
 * over its bounds or invalid, members no track can pair with (named by `members`) or that cannot each take a different track, an
 * Album without members, a match, more than one pairing (members without a duration, or not), or a single pairing left
 * unconfirmed by durations.
 */
export function candidateReason(candidate: Candidate, members: (slotIds: readonly string[]) => string): Message {
  const comparison = candidate.comparison, status = candidate.status, subset = comparison?.subset, unknown = comparison?.unknownLocalDurations ?? 0;
  const local = comparison?.trackCount.local, has = (difference: string) => comparison!.differences.includes(difference as never);
  if (status === 'incomplete' || !comparison) return { key: `lookup.status_${status}` };
  if (status === 'notMatching') return has('trackCount') ? reason('reason_too_few_tracks', { candidate: comparison.trackCount.candidate, local: local ?? 0 })
    : has('tooManyTracks') || has('tracklistInvalid') ? { key: `lookup.difference_${has('tooManyTracks') ? 'tooManyTracks' : 'tracklistInvalid'}` }
    : subset?.pairing !== 'none' ? { key: 'lookup.status_notMatching' }
    : subset.unpairableSlotIds.length ? reason('unpairable', { tracks: members(subset.unpairableSlotIds) }) : reason('reason_no_distinct');
  if (!local) return reason('reason_empty_album');
  if (status === 'matching') return reason('reason_matching', { count: local });
  return subset?.pairing === 'ambiguous' ? unknown ? reason('reason_no_durations', { count: unknown }) : reason('reason_ambiguous', { count: local })
    : subset?.pairing === 'unique' ? unknown ? reason('reason_paired_no_durations', { count: unknown }) : reason('reason_release_durations')
    : { key: 'lookup.status_unverified' };
}

/** "m:ss" of a duration, minutes not wrapped at an hour, never below 0:00. */
export const elapsedText = (ms: number) => { const seconds = Math.floor(Math.max(0, ms) / 1000) || 0; return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`; };
/** The message key of a progress phase, which the summary formats into the running line. */
export const progressPhaseKey = (phase: string) => `catalog_review.lookup_phase_${phase}`;

/**
 * What the review summary shows in place of the shared status: its messages (the polite status), the time a queued or running run
 * has waited or run (shown beside the status, outside it, as it moves with every read), whether filling the Disc and Track
 * Numbers from the titles is the next step (`next`, the only primary button) or offered beside the name box (`offer`), and
 * whether the status points at the name box (`box`, present only then).
 */
export type ReviewStatus = { messages: Message[]; elapsed?: Message; fill: 'next' | 'offer' | null; box?: true };
/**
 * The review's status in place of the shared next step's, or null to keep that one. A retrying run with its stored retry
 * (`timeline.retry`) says whether its source had too many requests (`sourceBusy`, also this server's own request bound) or is
 * unavailable, when it retries (formatted by `time`, else the ISO time) and which automatic retry of how many it is; without it
 * the shared copy stays. Where the shared status is unavailable because MusicBrainz's retries ran out, it says whether there were
 * too many requests or MusicBrainz stayed unavailable, and a stopped run says whether its administrator lost access or its time
 * ran out; the shared retry stays the next step in each. A queued or running run with `progress` says so and, while running, names
 * its phase and counts; its time counts from its start to the later of the summary's last read and its last step, so a client
 * clock behind the server's still counts. A release this run applied for its Album values only, whose pairing a saved number has
 * since made single, says that using it again brings in its tracklist. Where the shared step is no match (or iTunes was
 * unavailable besides, said after it), the first cause that applies: an Album without members (with a hint to add an Artist when
 * the run named none); else, among the releases the tracks fit (the possible matches, else those whose titles differ), a member
 * without a duration (or, once the pairing is single, that the release can be used), a single pairing a release track's unknown
 * duration left unconfirmed, or a pairing that is not single. Numbers are needed only while no such release pairs with the tracks
 * in one way. Entering them is the next step only where the titles give every member a Disc and Track Number (titleNumbers) and
 * the draft still lacks one (owner rules, next-step bullet); Track Numbers alone are offered after the name box, and otherwise the
 * copy says they can be entered in Edit draft, and, where a possible match is listed, that the tracks can be paired with it by hand.
 * The name box is the next step (`box`) for an Album without members and wherever the
 * numbers are needed but filling them is not the next step. Anything else is a real no match.
 */
export function reviewLookupStatus(lookup: ReviewLookupView, status: string,
  context: { members: number; searched: string; artists: readonly string[]; now: number; numbers: TitleNumbers | null; time?: (at: string) => string }): ReviewStatus | null {
  const progress = lookup.progress, retry = lookup.timeline?.retry, issue = lookup.issue;
  if (lookup.state === 'retrying' && retry) return { messages: [reason(`retry_${issue === 'sourceUnavailable' ? 'unavailable' : 'busy'}`, { source: retry.source === 'itunes' ? 'iTunes' : 'MusicBrainz',
    time: context.time ? context.time(retry.at) : retry.at, attempt: retry.attempt, limit: retry.limit })], fill: null };
  if (status === 'lookup.unavailable' && (issue === 'sourceBusy' || issue === 'sourceUnavailable')) return { messages: [reason(`exhausted_${issue === 'sourceBusy' ? 'busy' : 'unavailable'}`)], fill: null };
  if (lookup.state === 'stopped' && (issue === 'permissionLost' || issue === 'grantExpired')) return { messages: [reason(`stopped_${issue === 'grantExpired' ? 'time' : 'permission'}`)], fill: null };
  if (progress && (lookup.state === 'queued' || lookup.state === 'running')) {
    const elapsed = elapsedText(Math.max(context.now, Date.parse(progress.updatedAt) || 0) - Date.parse(progress.startedAt));
    return lookup.state === 'queued' ? { messages: [reason('queued_status')], elapsed: reason('waited', { elapsed }), fill: null }
      : { messages: [reason(progress.total ? 'running_count_status' : 'running_status', { phase: progress.phase, done: progress.done, total: progress.total })],
        elapsed: reason('elapsed', { elapsed }), fill: null };
  }
  const again = reviewAppliedAgain(lookup, status);
  if (again) return { messages: [reason('applied_album_only', { title: again.title ?? '—' })], fill: null };
  if (status !== 'lookup.no_match' && status !== 'lookup.itunes_unavailable') return null;
  const itunes = status === 'lookup.itunes_unavailable' ? [reason('itunes_note')] : [];
  const fit = reviewLookupFit(lookup, context);
  // An Album without members never matches, so the name box stays its next step (owner rules, next-step bullet).
  if (fit && !fit.members) return { messages: [reason('empty_album', { count: fit.releases.length }), ...(lookup.input.submitted?.artist || context.artists.length ? [] : [reason('add_artist')]),
    ...itunes], fill: null, box: true };
  if (!fit) return null;
  const { cause, unknown } = fit, numbers = context.numbers, needed = cause === 'durations' || cause === 'pairing', next = needed && Boolean(numbers?.disc && numbers.count);
  return { messages: [reason(fit.possible ? 'possible_found' : 'fit_found', { count: fit.releases.length, title: fit.releases[0][0].title ?? '—' }),
    reason(`cause_${cause}${needed && !next ? (fit.possible ? '_pair' : '_manual') : ''}`, unknown ? { unknown } : undefined), ...itunes], fill: next ? 'next' : needed && numbers?.count ? 'offer' : null,
    ...(needed && !next ? { box: true as const } : {}) };
}
